import type { NextConfig } from 'next';

const nextConfig: NextConfig = {
  reactStrictMode: true,
};

export default nextConfig;

/** @type {import('postcss-load-config').Config} */
const config = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

export default config;

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  @apply bg-gray-50 text-gray-900;
}

import { readFile, writeFile } from 'fs/promises';
import path from 'path';

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  finished: boolean;
};

const DATA_PATH = path.join(process.cwd(), 'data', 'books.json');

async function ensureFile() {
  try {
    await readFile(DATA_PATH, 'utf-8');
  } catch {
    await writeFile(DATA_PATH, JSON.stringify([], null, 2), 'utf-8');
  }
}

export async function getBooks(): Promise<Book[]> {
  await ensureFile();
  const raw = await readFile(DATA_PATH, 'utf-8');
  return JSON.parse(raw) as Book[];
}

export async function saveBooks(books: Book[]) {
  await ensureFile();
  await writeFile(DATA_PATH, JSON.stringify(books, null, 2), 'utf-8');
}

export async function getBook(id: string): Promise<Book | undefined> {
  const books = await getBooks();
  return books.find((book) => book.id === id);
}

export async function addBook(book: Omit<Book, 'id' | 'finished'>) {
  const books = await getBooks();
  const newBook: Book = {
    ...book,
    id: crypto.randomUUID(),
    finished: false,
  };
  books.push(newBook);
  await saveBooks(books);
  return newBook;
}

export async function finishBook(id: string) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (book) {
    book.finished = true;
    await saveBooks(books);
  }
  return book;
}

export async function updateBook(id: string, updates: Partial<Book>) {
  const books = await getBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return undefined;
  books[index] = { ...books[index], ...updates };
  await saveBooks(books);
  return books[index];
}

import { NextResponse } from 'next/server';
import { addBook, getBooks } from '@/lib/books';

export async function GET() {
  const books = await getBooks();
  return NextResponse.json(books);
}

export async function POST(request: Request) {
  const body = await request.json();
  const book = await addBook({
    title: String(body.title || ''),
    author: String(body.author || ''),
    notes: String(body.notes || ''),
  });
  return NextResponse.json(book, { status: 201 });
}

import { NextResponse } from 'next/server';
import { finishBook, getBook } from '@/lib/books';

export async function GET(
  _request: Request,
  { params }: { params: { id: string } }
) {
  const book = await getBook(params.id);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json(book);
}

export async function PATCH(
  request: Request,
  { params }: { params: { id: string } }
) {
  const body = await request.json();
  const book = await finishBook(params.id);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json(book);
}

export const metadata = {
  title: 'Reading Log',
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body className="max-w-3xl mx-auto p-6">{children}</body>
    </html>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import type { Book } from '@/lib/books';

export default function HomePage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [notes, setNotes] = useState('');

  async function loadBooks() {
    const res = await fetch('/api/books');
    setBooks(await res.json());
  }

  useEffect(() => {
    loadBooks();
  }, []);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    await fetch('/api/books', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title, author, notes }),
    });
    setTitle('');
    setAuthor('');
    setNotes('');
    await loadBooks();
  }

  async function finish(id: string) {
    await fetch(`/api/books/${id}`, { method: 'PATCH' });
    await loadBooks();
  }

  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  return (
    <main>
      <h1 className="text-2xl font-bold mb-6">Reading Log</h1>

      <form onSubmit={handleSubmit} className="bg-white p-4 rounded shadow mb-8 space-y-4">
        <h2 className="font-semibold">Add a book</h2>
        <div>
          <label className="block text-sm font-medium">Title</label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            required
            className="w-full border rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm font-medium">Author</label>
          <input
            type="text"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            required
            className="w-full border rounded px-3 py-2"
          />
        </div>
        <div>
          <label className="block text-sm font-medium">Notes</label>
          <textarea
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            rows={3}
            className="w-full border rounded px-3 py-2"
          />
        </div>
        <button
          type="submit"
          className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          Add book
        </button>
      </form>

      <section className="mb-8">
        <h2 className="font-semibold mb-3">Currently reading</h2>
        {reading.length === 0 ? (
          <p className="text-gray-600">No books yet.</p>
        ) : (
          <ul className="space-y-3">
            {reading.map((book) => (
              <li key={book.id} className="bg-white p-4 rounded shadow flex items-center justify-between">
                <Link href={`/book/${book.id}`} className="font-medium hover:underline">
                  {book.title}
                </Link>
                <span className="text-sm text-gray-600">{book.author}</span>
                <button
                  onClick={() => finish(book.id)}
                  className="text-sm bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
                >
                  Finish
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2 className="font-semibold mb-3">Finished</h2>
        {finished.length === 0 ? (
          <p className="text-gray-600">No finished books yet.</p>
        ) : (
          <ul className="space-y-3">
            {finished.map((book) => (
              <li key={book.id} className="bg-white p-4 rounded shadow">
                <Link href={`/book/${book.id}`} className="font-medium hover:underline">
                  {book.title}
                </Link>
                <p className="text-sm text-gray-600">{book.author}</p>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}

import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getBook } from '@/lib/books';

export default async function BookPage({ params }: { params: { id: string } }) {
  const book = await getBook(params.id);
  if (!book) notFound();

  return (
    <main>
      <Link href="/" className="text-blue-600 hover:underline text-sm">
        ← Back to reading log
      </Link>
      <h1 className="text-2xl font-bold mt-4 mb-2">{book.title}</h1>
      <p className="text-gray-700 mb-6">by {book.author}</p>
      <div className="bg-white p-4 rounded shadow">
        <h2 className="font-semibold mb-2">Notes</h2>
        {book.notes ? (
          <p className="whitespace-pre-wrap">{book.notes}</p>
        ) : (
          <p className="text-gray-600 italic">No notes yet.</p>
        )}
      </div>
      <p className="mt-6 text-sm text-gray-600">
        {book.finished ? 'Finished' : 'Currently reading'}
      </p>
    </main>
  );
}

